#include <torch/extension.h>
#include <cuda_runtime.h>

#define THREADS 256

__global__ void stats_kernel(const float4* __restrict__ x, float2* __restrict__ ps, long ns4, int S) {
    int pid = blockIdx.x;
    int row = pid / S;
    int part = pid % S;
    long chunk = ns4 / S;
    const float4* xp = x + (long)row * ns4 + (long)part * chunk;
    float s = 0.f, ss = 0.f;
    for (long i = threadIdx.x; i < chunk; i += THREADS) {
        float4 v = xp[i];
        s += v.x + v.y + v.z + v.w;
        ss += v.x*v.x + v.y*v.y + v.z*v.z + v.w*v.w;
    }
    __shared__ float sh[THREADS * 2];
    sh[threadIdx.x] = s;
    sh[threadIdx.x + THREADS] = ss;
    __syncthreads();
    for (int o = THREADS/2; o > 0; o >>= 1) {
        if (threadIdx.x < o) {
            sh[threadIdx.x] += sh[threadIdx.x + o];
            sh[threadIdx.x + THREADS] += sh[threadIdx.x + THREADS + o];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        ps[pid * 2] = sh[0];
        ps[pid * 2 + 1] = sh[THREADS];
    }
}

__global__ void norm_kernel(const float4* __restrict__ x, const float4* __restrict__ w, const float4* __restrict__ b,
                            float4* __restrict__ y, const float2* __restrict__ mr, long ns4, int rpc, int S) {
    int pid = blockIdx.x;
    int row = pid / rpc;
    int rc = pid % rpc;
    float2 m = mr[row];
    float mean = m.x, rstd = m.y;
    long base = (long)row * ns4;
    for (long i = (long)rc * (ns4 / S / 4) + threadIdx.x + (long)blockIdx.y * THREADS; ; ) { break; }
    long chunk = ns4 / rpc;
    const float4* xp = x + base + (long)rc * chunk;
    const float4* wp = w + (long)rc * chunk;
    const float4* bp = b + (long)rc * chunk;
    float4* yp = y + base + (long)rc * chunk;
    for (long i = threadIdx.x; i < chunk; i += THREADS) {
        float4 v = xp[i];
        float4 wv = wp[i];
        float4 bv = bp[i];
        float4 o;
        o.x = (v.x - mean) * rstd * wv.x + bv.x;
        o.y = (v.y - mean) * rstd * wv.y + bv.y;
        o.z = (v.z - mean) * rstd * wv.z + bv.z;
        o.w = (v.w - mean) * rstd * wv.w + bv.w;
        yp[i] = o;
    }
}

__global__ void mid_kernel(const float2* __restrict__ ps, float2* __restrict__ mr, float invns, int S) {
    int row = blockIdx.x;
    const float2* p = ps + row * S * 2 / 2;  // ps is float2 per partial? careful
    float s = 0.f, ss = 0.f;
    for (int i = threadIdx.x; i < S; i += THREADS) {
        float2 v = ps[row * S + i];
        s += v.x;
        ss += v.y;
    }
    __shared__ float sh[THREADS * 2];
    sh[threadIdx.x] = s;
    sh[threadIdx.x + THREADS] = ss;
    __syncthreads();
    for (int o = THREADS/2; o > 0; o >>= 1) {
        if (threadIdx.x < o) {
            sh[threadIdx.x] += sh[threadIdx.x + o];
            sh[threadIdx.x + THREADS] += sh[threadIdx.x + THREADS + o];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        float total = sh[0];
        float total2 = sh[THREADS];
        float mean = total * invns;
        float var = total2 * invns - mean * mean;
        mr[row] = make_float2(mean, rsqrtf(var + 1e-5f));
    }
}

std::vector<torch::Tensor> ln_forward(torch::Tensor x, torch::Tensor w, torch::Tensor b, torch::Tensor ps, torch::Tensor mr, int64_t rows, int64_t ns, int64_t S, int64_t rpc) {
    auto y = torch::empty_like(x);
    long ns4 = ns / 4;
    auto stream = at::cuda::getCurrentCUDAStream();
    stats_kernel<<<rows * S, THREADS, 0, stream>>>((const float4*)x.data_ptr<float>(), (float2*)ps.data_ptr<float>(), ns4, (int)S);
    mid_kernel<<<rows, THREADS, 0, stream>>>((const float2*)ps.data_ptr<float>(), (float2*)mr.data_ptr<float>(), 1.0f / (float)ns, (int)S);
    norm_kernel<<<rows * rpc, THREADS, 0, stream>>>((const float4*)x.data_ptr<float>(), (const float4*)w.data_ptr<float>(), (const float4*)b.data_ptr<float>(), (float4*)y.data_ptr<float>(), (const float2*)mr.data_ptr<float>(), ns4, (int)rpc, (int)S);
    return {y};
}
